        's_whose_all' => '<strong>அனைவரும்</strong> &mdash; முழு நிறுவல். இதுவே இயல்புநிலை, Watchtower எப்போதும் காட்டி வந்ததும் இதுவே, எனவே நீங்கள் கேட்காத வரை எதுவும் மாறாது.',
        's_whose_narrows' => 'நான்கு அட்டைகள் சுருங்குகின்றன: <strong>டிக்கெட்டுகள்</strong>, <strong>பணிகள்</strong>, <strong>மாற்றங்கள்</strong> மற்றும் <strong>காலை சரிபார்ப்புகள்</strong>. அவற்றிலுள்ள ஒவ்வொரு எண்ணும் மாற்றியைப் பின்பற்றுகிறது &mdash; உங்கள் திறந்த டிக்கெட்டுகள் நிலை வாரியாக, உங்கள் தாமதமான பணிகள், உங்களுக்கு ஒதுக்கப்பட்ட மாற்றங்கள்.',
        's_whose_impersonal' => '<strong>எட்டு அட்டைகள் சுருங்க முடியாது; அவை <em>அனைவரும்</em> என்று குறிக்கப்பட்டுள்ளன, எனவே குழு முழுவதற்குமான எண்ணை நீங்கள் தனிப்பட்ட எண்ணாக ஒருபோதும் படிக்க மாட்டீர்கள்.</strong> பாதிக்கப்பட்ட சேவையும் தோல்வியடைந்த பணிப்பாய்வும் யாருக்கும் சொந்தமில்லை. உபகரணங்கள் பகுப்பாய்வாளர்களுக்கு அல்லாமல் <em>இறுதிப் பயனர்களுக்கு</em> ஒதுக்கப்படுகின்றன, எனவே &ldquo;என் உபகரணங்கள்&rdquo; கிட்டத்தட்ட எல்லோருக்கும் காலியாக இருக்கும். நாட்காட்டி அட்டை பகிரப்பட்ட குழு நாட்காட்டி. ஒப்பந்தங்களும் அறிவுத்தளமும் உரிமையாளரைப் பதிவு செய்கின்றன, ஆனால் காலாவதியாகவிருக்கும் ஒப்பந்தத்தை யார் உரிமையாளராக இருந்தாலும் பின்தொடர வேண்டும், மறுஆய்வு தாமதமான கட்டுரை ஒருவரின் வேலைச்சுமையில் அல்ல, நூலகத்தில் உள்ள இடைவெளி. மென்பொருள் உரிமங்களும் டொமைன்களும் அதேபோலத்தான்: புதுப்பித்தலில் யார் பெயர் இருந்தாலும் அதைக் கையாள வேண்டும்.',
        's_whose_unassigned' => '<strong>ஒதுக்கப்படாத டிக்கெட்டுகள் ஒருபோதும் சுருங்காது</strong>, எந்த அமைப்பிலும். ஒதுக்கப்படாத டிக்கெட் வரையறையின்படி உங்களுடையது அல்ல, எனவே &ldquo;என்னுடையது&rdquo; என்பது எப்போதும் பூஜ்ஜியத்தைக் காட்டும் &mdash; அங்கே பூஜ்ஜியம் <em>வரிசை காலியாக உள்ளது</em> என்று படிக்கப்படும், உரிமை கோரப்படாத குவியல் என்பதன் எதிர்மாறு அது.',
        's_whose_checks' => '<strong>காலை சரிபார்ப்புகள் அவற்றின் குழு வழியாகப் பொருத்தப்படுகின்றன.</strong> ஒரு சரிபார்ப்பை ஒரு குழுவில் வைத்து, அந்தக் குழுவை ஒரு அணிக்கு அல்லது ஒரு நபருக்குச் சுட்டிக்காட்டுவதன் மூலம் அது வழிப்படுத்தப்படுகிறது; எனவே <em>என்னுடையது</em> என்பது உங்களுக்கு ஒதுக்கப்பட்ட சரிபார்ப்புகள், உங்களைச் சுட்டும் குழுவில் உள்ள சரிபார்ப்புகள், அல்லது நீங்கள் உள்ள குழுவைச் சுட்டும் குழுவில் உள்ள சரிபார்ப்புகள் என்று பொருள்.',
        's_whose_setting' => 'நீங்கள் <strong>என்னுடையது</strong> என்பதில் இருக்கும்போது அந்த எட்டு அட்டைகளுக்கு என்ன நடக்கும் என்பது உங்கள் சொந்தத் தேர்வு, <strong>விருப்பத்தேர்வுகள் &rarr; பொது</strong> என்பதில்: அவற்றைத் தொடர்ந்து காட்டலாம், அல்லது முற்றிலும் தனிப்பட்ட பலகைக்காக மறைக்கலாம். இயல்பாக அவை வைக்கப்படுகின்றன, ஏனெனில் நீங்கள் உங்கள் சொந்த வேலைக்கு மாறியதால் மறைந்துபோகக் கூடாத கடைசி விஷயம் பாதிக்கப்பட்ட சேவை.',
        'nav_cards' => 'தொகுதி அட்டைகள் விளக்கப்பட்டுள்ளன',
        'nav_refresh' => 'தானியங்கி புதுப்பிப்பு',
        'nav_tips' => 'விரைவு குறிப்புகள்',
        'nav_settings' => 'அமைப்புகள்',
        's1_title' => 'மேலோட்டம்',
        's1_intro' => 'Watchtower என்பது உங்கள் IT செயல்பாடுகளுக்கான ஒரே கண்ணாடிப் பலகம். அவசர உருப்படிகளைச் சரிபார்க்க ஒவ்வொரு தொகுதியையும் தனித்தனியாகத் திறப்பதற்குப் பதிலாக, ஒவ்வொரு தொகுதியிலிருந்தும் மிக முக்கியமான தகவல்களை Watchtower ஒரே டாஷ்போர்டில் கொண்டுவருகிறது. ஒரே பார்வையில் எதற்குக் கவனம் தேவை, எது சீராக இயங்குகிறது, உங்கள் நேரத்தை எங்கே செலுத்த வேண்டும் என்பதை நீங்கள் காணலாம்.',
        's1_feat1_title' => 'கவனப் பலகை',
        's1_feat1_desc' => 'அனைத்து தொகுதிகளிலும் உங்கள் கவனம் தேவைப்படுவதை ஒரே இடத்தில் காணுங்கள். காலை சரிபார்ப்புகள், டிக்கெட்டுகள், மாற்றங்கள், நாட்காட்டி நிகழ்வுகள், சேவை நிலை, ஒப்பந்தங்கள், அறிவுத்தளக் கட்டுரைகள் மற்றும் சொத்துகள் அனைத்தும் ஒரே திரையில் சுருக்கப்படுகின்றன.',
        's1_feat2_title' => 'நிறக் குறியீட்டு நிலை',
        's1_feat2_desc' => 'ஒவ்வொரு தொகுதி அட்டையும் உடனடி வகைப்படுத்தலுக்காக பச்சை, அம்பர் அல்லது சிவப்பு நிலை புள்ளியைக் காட்டுகிறது. எந்தப் பகுதிகள் ஆரோக்கியமாக உள்ளன, எவை கவனம் தேவைப்படுகின்றன, எவை உடனடி நடவடிக்கை தேவைப்படுகின்றன என்பதை ஒரே பார்வையில் நீங்கள் சொல்லலாம்.',
        's1_feat3_title' => 'தானியங்கி புதுப்பிப்பு',
        's1_feat3_desc' => 'டாஷ்போர்டு ஒவ்வொரு 5 நிமிடங்களுக்கும் தானாகவே புதுப்பிக்கப்படுகிறது, எனவே எந்த கைமுறை நடவடிக்கையும் இல்லாமல் தகவல் நடப்பு நிலையில் இருக்கும். Watchtower-ஐ திறந்து வைத்திருங்கள், அது பின்னணியில் தன்னைத்தானே புதுப்பித்துக் கொள்ளும்.',
        's1_feat4_title' => 'கிளிக்-த்ரூ',
        's1_feat4_desc' => 'அதன் அட்டையிலிருந்து நேரடியாக எந்தத் தொகுதிக்கும் தாவுங்கள். ஒவ்வொரு தொகுதி பெயரும் கிளிக் செய்யக்கூடிய இணைப்பாகும், இது தொடர்புடைய பகுதிக்கு நேராக உங்களை அழைத்துச் செல்கிறது, எனவே சரியான பக்கத்தைத் தேடாமல் சிக்கல்களில் நீங்கள் நடவடிக்கை எடுக்கலாம்.',
        's2_title' => 'டாஷ்போர்டு அமைப்பு',
        's2_p1' => 'Watchtower டாஷ்போர்டு தொகுதி அட்டைகளின் பதிலளிக்கக்கூடிய 3-நெடுவரிசை கட்டத்தைப் பயன்படுத்துகிறது. சிறிய திரைகளில் கட்டம் 2 நெடுவரிசைகள் அல்லது ஒற்றை நெடுவரிசைக்கு மாறிக்கொள்கிறது, எனவே இது எந்தச் சாதனத்திலும் வேலை செய்கிறது. கட்டத்திற்கு மேலே புதுப்பிப்பு பொத்தான் மற்றும் தரவு கடைசியாக எப்போது பெறப்பட்டது என்பதைக் காட்டும் "புதுப்பிக்கப்பட்டது" நேரமுத்திரையுடன் தலைப்புப் பட்டை உள்ளது.',
        's2_p2' => 'கட்டத்தில் உள்ள ஒவ்வொரு அட்டையும் ஒரு சீரான கட்டமைப்பைப் பின்பற்றுகிறது, இதனால் நீங்கள் அவற்றை விரைவாக ஸ்கேன் செய்யலாம்:',
        's2_diagram_name' => 'தொகுதி பெயர்',
        's2_diagram_open' => 'திறந்தவை',
        's2_diagram_active' => 'செயலில்',
        's2_diagram_hold' => 'நிறுத்தம்',
        's2_diagram_clear' => 'அனைத்தும் தெளிவு — அவசர உருப்படிகள் இல்லை',
        's2_field_icon' => '<strong>நிறமிட்ட சின்னம்</strong> &mdash; தொகுதியின் தீம் நிறத்தில் உள்ள ஒரு சிறிய சதுர சின்னம் (காலை சரிபார்ப்புகளுக்கு டீல், டிக்கெட்டுகளுக்கு நீலம், போன்றவை) இதனால் ஒவ்வொரு அட்டையையும் உடனடியாக அடையாளம் காணலாம்.',
        's2_field_name' => '<strong>தொகுதி பெயர்</strong> &mdash; அந்தத் தொகுதிக்கு நேரடியாக வழிநடத்தும் கிளிக் செய்யக்கூடிய இணைப்பு. நேராகத் தாவி நடவடிக்கை எடுக்க கிளிக் செய்யுங்கள்.',
        's2_field_dot' => '<strong>நிலை புள்ளி</strong> &mdash; அந்தத் தொகுதிக்கான ஒட்டுமொத்த அவசர நிலையைக் காட்டும் மேல்-வலது மூலையில் உள்ள பச்சை, அம்பர் அல்லது சிவப்பு புள்ளி.',
        's2_field_metrics' => '<strong>முக்கிய அளவீடுகள்</strong> &mdash; மிக முக்கியமான எண்ணிக்கைகளைச் சுருக்கும் பெரிய எண்கள் (எ.கா. திறந்த டிக்கெட்டுகள், முடிக்கப்பட்ட சரிபார்ப்புகள், காலாவதியாகும் ஒப்பந்தங்கள்).',
        's2_field_attention' => '<strong>கவன உருப்படிகள்</strong> &mdash; அந்தத் தொகுதிக்குள் குறிப்பாக எதற்கு உங்கள் கவனம் தேவை என்பதை முன்னிலைப்படுத்தும் நிறக் குறியீட்டு செய்தி வரிகள்.',
        's2_tip' => 'அட்டை அமைப்பு ஆழமான பகுப்பாய்வுக்காக அல்ல, ஸ்கேன் செய்வதற்காக வடிவமைக்கப்பட்டுள்ளது. எந்தத் தொகுதிகளுக்கு உங்கள் கவனம் தேவை என்பதைக் கண்டறிய Watchtower-ஐப் பயன்படுத்தி, பின்னர் முழு விவரங்களுக்காக தொகுதிக்கே கிளிக் செய்யுங்கள்.',
        's3_title' => 'நிலை புள்ளிகளைப் புரிந்துகொள்ளுதல்',
        's3_intro' => 'ஒவ்வொரு தொகுதி அட்டையும் அதன் தலைப்பில் ஒரு நிலை புள்ளியைக் காட்டுகிறது. உங்கள் IT செயல்பாடுகளின் அந்தப் பகுதிக்கு கவனம் தேவையா என்பதற்கான உடனடி காட்சி குறிகாட்டியை இந்தப் புள்ளி வழங்குகிறது. ஒவ்வொரு தொகுதியிலிருந்தும் திரும்பிய தரவின் அடிப்படையில் நிறம் தானாகவே தீர்மானிக்கப்படுகிறது.',
        's3_green_label' => 'பச்சை',
        's3_green_desc' => 'எல்லாம் நன்றாக உள்ளது. எந்த நடவடிக்கையும் தேவையில்லை. தீர்க்கப்படாத சிக்கல்கள் அல்லது கவனம் தேவைப்படும் உருப்படிகள் எதுவும் இல்லாமல் தொகுதி ஆரோக்கியமான நிலையில் உள்ளது.',
        's3_green_examples' => '<strong>எடுத்துக்காட்டுகள்:</strong> அனைத்து காலை சரிபார்ப்புகளும் வெற்றி, அவசர டிக்கெட்டுகள் இல்லை, அனைத்து அமைப்புகளும் இயங்குகின்றன, விரைவில் காலாவதியாகும் ஒப்பந்தங்கள் இல்லை.',
        's3_amber_label' => 'அம்பர்',
        's3_amber_desc' => 'ஏதோ கவனம் தேவைப்படுகிறது ஆனால் முக்கியமானதல்ல. வாய்ப்பு கிடைக்கும்போது நீங்கள் மறுஆய்வு செய்ய வேண்டிய உருப்படிகள் உள்ளன, ஆனால் எதுவும் தீப்பற்றவில்லை.',
        's3_amber_examples' => '<strong>எடுத்துக்காட்டுகள்:</strong> எச்சரிக்கைகளுடன் சரிபார்ப்புகள், ஒதுக்கப்படாத டிக்கெட்டுகள், ஒப்புதலுக்காக காத்திருக்கும் மாற்றங்கள், 90 நாட்களுக்குள் காலாவதியாகும் ஒப்பந்தங்கள்.',
        's3_red_label' => 'சிவப்பு',
        's3_red_desc' => 'அவசர உருப்படிகளுக்கு உடனடி நடவடிக்கை தேவை. ஏதோ தோல்வியடைந்துள்ளது, தாமதமாகியுள்ளது அல்லது தீவிரமாகப் பாதிக்கப்பட்டுள்ளது மற்றும் உடனடியாகக் கவனிக்கப்பட வேண்டும்.',
        's3_red_examples' => '<strong>எடுத்துக்காட்டுகள்:</strong> காலை சரிபார்ப்புகள் தொடங்கப்படவில்லை அல்லது தோல்வியடைந்தன, அவசர/உயர் முன்னுரிமை டிக்கெட்டுகள், பெரிய சேவை முடக்கங்கள், 30 நாட்களுக்குள் காலாவதியாகும் ஒப்பந்தங்கள்.',
        's3_tip' => 'புள்ளிகளை போக்குவரத்து விளக்குகள் போல நினைத்துக் கொள்ளுங்கள். பச்சை என்றால் உங்கள் வேலையைத் தொடருங்கள், அம்பர் என்றால் முடிந்தபோது மறுஆய்வு செய்யுங்கள், சிவப்பு என்றால் செய்துகொண்டிருப்பதை நிறுத்திவிட்டு விசாரியுங்கள். அனைத்துப் புள்ளிகளையும் பச்சையாக வைத்திருப்பதே இலக்கு.',
        's4_title' => 'தொகுதி அட்டைகள் விளக்கப்பட்டுள்ளன',
        's4_intro' => 'Watchtower-இல் பதின்மூன்று அட்டைகள் உள்ளன, அது கண்காணிக்கும் ஒவ்வொரு பகுதிக்கும் ஒன்று. ஒவ்வொரு அட்டையும் அந்தப் பகுதிக்கு மிகவும் பொருத்தமான தகவலைக் காட்ட வடிவமைக்கப்பட்டுள்ளது. முக்கிய அட்டைகள் எதைக் காட்டுகின்றன, அவற்றின் நிலைப் புள்ளி நிறத்தை எது தூண்டுகிறது என்பது இங்கே.',
        's4_mc_title' => 'காலை சரிபார்ப்புகள்',
        's4_mc_desc' => 'நிறைவு முன்னேற்றத்தைக் காட்டுகிறது (எ.கா. 8/10 முடிந்தது) மற்றும் சரி, எச்சரிக்கை, தோல்வி முடிவுகளின் எண்ணிக்கைகள். சரிபார்ப்புகள் தொடங்கப்படாதபோது அல்லது ஏதேனும் தோல்வியடைந்தபோது கவன உருப்படிகள் கொடியிடுகின்றன.',
        's4_mc_triggers' => '<strong>சிவப்பு:</strong> இன்று சரிபார்ப்புகள் தொடங்கப்படவில்லை, அல்லது ஏதேனும் சரிபார்ப்புகள் தோல்வியடைந்தன. <strong>அம்பர்:</strong> சரிபார்ப்புகள் முழுமையடையவில்லை அல்லது எச்சரிக்கைகள் உள்ளன. <strong>பச்சை:</strong> அனைத்து சரிபார்ப்புகளும் முடிந்து வெற்றியடைந்தன.',
        's4_tk_title' => 'டிக்கெட்டுகள்',
        's4_tk_desc' => 'மொத்தத் திறந்த எண்ணிக்கையை புதியவை, செயலில் மற்றும் நிறுத்தத்தில் என்று பிரித்துக் காட்டுகிறது. கவன உருப்படிகள் அவசர/உயர் முன்னுரிமை டிக்கெட்டுகள் மற்றும் ஒதுக்கப்படாதவற்றை முன்னிலைப்படுத்துகின்றன.',
        's4_tk_triggers' => '<strong>சிவப்பு:</strong> அவசர அல்லது உயர் முன்னுரிமை டிக்கெட்டுகள் உள்ளன. <strong>அம்பர்:</strong> ஒதுக்கப்படாத டிக்கெட்டுகள் உள்ளன. <strong>பச்சை:</strong> அவசர உருப்படிகள் அல்லது ஒதுக்கப்படாத டிக்கெட்டுகள் இல்லை.',
        's4_ch_title' => 'மாற்றங்கள்',
        's4_ch_desc' => 'அடுத்த 7 நாட்களில் திட்டமிடப்பட்ட மாற்றங்களின் எண்ணிக்கை, தற்போது எத்தனை நடைபெறுகின்றன, எத்தனை ஒப்புதலுக்கு நிலுவையில் உள்ளன என்பதைக் காட்டுகிறது. கவன உருப்படிகள் ஒப்புதலளிக்கப்படாத மற்றும் செயலில் உள்ள மாற்றங்களை சுட்டிக்காட்டுகின்றன.',
        's4_ch_triggers' => '<strong>அம்பர்:</strong> மாற்றங்கள் ஒப்புதலுக்காக காத்திருக்கின்றன. <strong>பச்சை:</strong> ஒப்புதலளிக்கப்படாத மாற்றங்கள் இல்லை.',
        's4_cal_title' => 'நாட்காட்டி',
        's4_cal_desc' => 'இன்று மற்றும் இந்த வாரத்தில் உள்ள நிகழ்வுகளின் எண்ணிக்கையைக் காட்டுகிறது. இன்று நிகழ்வுகள் இருந்தால், அவை அவற்றின் நேரங்களுடன் பட்டியலிடப்படுகின்றன (அல்லது நாள் முழுவதும் நிகழ்வுகளுக்கு "நாள் முழுவதும்").',
        's4_cal_triggers' => '<strong>அம்பர்:</strong> இன்றைக்காக திட்டமிடப்பட்ட நிகழ்வுகள். <strong>பச்சை:</strong> இன்று நிகழ்வுகள் இல்லை.',
        's4_ss_title' => 'சேவை நிலை',
        's4_ss_desc' => 'செயலில் உள்ள சம்பவங்களின் எண்ணிக்கையைக் காட்டுகிறது மற்றும் பாதிக்கப்பட்ட சேவைகளை அவற்றின் தாக்க நிலை குறிச்சொற்களுடன் (பெரிய முடக்கம், பகுதி முடக்கம், தரம் குறைந்தது, பராமரிப்பு) பட்டியலிடுகிறது. எல்லாம் ஆரோக்கியமாக இருக்கும்போது, பச்சை "அனைத்து அமைப்புகளும் இயங்குகின்றன" பதாகை தோன்றுகிறது.',
        's4_ss_triggers' => '<strong>சிவப்பு:</strong> எந்தச் சேவையிலும் பெரிய அல்லது பகுதி முடக்கம். <strong>அம்பர்:</strong> தரம் குறைந்த அல்லது பராமரிப்பு நிலை. <strong>பச்சை:</strong> அனைத்து அமைப்புகளும் இயங்குகின்றன.',
        's4_ct_title' => 'ஒப்பந்தங்கள்',
        's4_ct_desc' => '30 நாட்களுக்குள், 90 நாட்களுக்குள் காலாவதியாகும் ஒப்பந்தங்கள் மற்றும் நெருங்கும் அறிவிப்பு காலங்களைக் காட்டுகிறது. கவன உருப்படிகள் உடனடி காலாவதிகள் மற்றும் வரவிருக்கும் அறிவிப்பு காலக்கெடுக்கள் குறித்து எச்சரிக்கின்றன.',
        's4_ct_triggers' => '<strong>சிவப்பு:</strong> 30 நாட்களுக்குள் காலாவதியாகும் ஒப்பந்தங்கள். <strong>அம்பர்:</strong> 90 நாட்களுக்குள் காலாவதியாகும் ஒப்பந்தங்கள் அல்லது நெருங்கும் அறிவிப்பு காலங்கள். <strong>பச்சை:</strong> கவனம் தேவைப்படும் ஒப்பந்தங்கள் இல்லை.',
        's4_sw_title' => 'மென்பொருள்',
        's4_sw_desc' => '30 நாட்களுக்குள், 90 நாட்களுக்குள் புதுப்பிக்கப்பட வேண்டிய மென்பொருள் உரிமங்களையும், தீர்ந்துவரும் அறிவிப்புக் காலங்களையும் காட்டுகிறது. உரிமப் புதுப்பித்தல் தேதிகள் எப்போதும் பதிவில் இருந்தன; காலாவதியாகும் முன் ஒன்றைக் கண்ணுக்குத் தெரியச் செய்வது இதுவே.',
        's4_sw_triggers' => '<strong>சிவப்பு:</strong> 30 நாட்களுக்குள் புதுப்பிக்கப்பட வேண்டிய உரிமங்கள். <strong>அம்பர்:</strong> 90 நாட்களுக்குள் புதுப்பிக்கப்பட வேண்டிய உரிமங்கள் அல்லது நெருங்கும் அறிவிப்புக் காலங்கள். <strong>பச்சை:</strong> கவனம் தேவைப்படும் மென்பொருள் புதுப்பித்தல்கள் இல்லை. புதுப்பித்தல் தேதிகள் எதுவுமே பதிவு செய்யப்படாதபோது, காலிப் பட்டியலில் அனைத்தும் சரி என்று காட்டாமல், அட்டை அதை வெளிப்படையாகக் கூறுகிறது.',
        's4_kb_title' => 'அறிவுத்தளம்',
        's4_kb_desc' => 'மறுஆய்வுக்கு தாமதமான கட்டுரைகளின் எண்ணிக்கையைக் காட்டுகிறது மற்றும் இந்த வாரம் சமீபத்தில் வெளியிடப்பட்ட கட்டுரைகளைப் பட்டியலிடுகிறது. மறுஆய்வுகள் எதுவும் தாமதமாகாமல் அறிவுத்தளம் நடப்பு நிலையில் இருக்கும்போது, அட்டை அனைத்தும்-தெளிவு செய்தியைக் காட்டுகிறது.',
        's4_kb_triggers' => '<strong>அம்பர்:</strong> மறுஆய்வுக்கு தாமதமான கட்டுரைகள். <strong>பச்சை:</strong> அறிவுத்தளம் புதுப்பித்த நிலையில் உள்ளது.',
        's4_as_title' => 'சொத்துகள்',
        's4_as_desc' => 'கண்காணிக்கப்படும் சொத்துகளின் மொத்த எண்ணிக்கையையும் எத்தனை 7 அல்லது அதற்கு மேற்பட்ட நாட்களாக காணப்படவில்லை என்பதையும் காட்டுகிறது. இது ஆஃப்லைனாக, செயல்நீக்கப்பட்ட அல்லது தொலைந்த சாதனங்களை அடையாளம் காண உதவுகிறது.',
        's4_as_triggers' => '<strong>அம்பர்:</strong> 7+ நாட்களாக காணப்படாத சொத்துகள். <strong>பச்சை:</strong> அனைத்து சொத்துகளும் சமீபத்தில் செயலில் இருந்தன.',
        's5_title' => 'தானியங்கி புதுப்பிப்பு மற்றும் கைமுறை புதுப்பிப்பு',
        's5_intro' => 'Watchtower என்பது நாள் முழுவதும் உலாவி தாவலில் திறந்து வைத்திருக்கக்கூடிய ஒரு செயலற்ற கண்காணிப்புக் கருவியாக வடிவமைக்கப்பட்டுள்ளது. தானியங்கி புதுப்பிப்பு சுழற்சிகள் மூலம் டாஷ்போர்டு தன்னை நடப்பு நிலையில் வைத்திருக்கிறது.',
        's5_step1' => '<strong>தானியங்கி புதுப்பிப்பு</strong> &mdash; டாஷ்போர்டு ஒவ்வொரு 5 நிமிடங்களுக்கும் அனைத்து தொகுதிகளிலிருந்தும் புதிய தரவைப் பெறுகிறது. நீங்கள் பக்கத்தை மீண்டும் ஏற்ற வேண்டிய அல்லது எதையும் கிளிக் செய்ய வேண்டிய அவசியமில்லை; அட்டைகளும் நிலை புள்ளிகளும் பின்னணியில் அமைதியாக புதுப்பிக்கப்படுகின்றன.',
        's5_step2' => '<strong>கைமுறை புதுப்பிப்பு</strong> &mdash; சமீபத்திய தரவை உடனடியாகப் பெற மேல்-வலது மூலையில் உள்ள <strong>புதுப்பி</strong> பொத்தானைக் கிளிக் செய்யுங்கள். கோரிக்கை நடைபெறும்போது பொத்தான் சின்னம் சுழல்கிறது, புதிய தரவு ஏற்றப்படுவதை உறுதிப்படுத்துகிறது.',
        's5_step3' => '<strong>புதுப்பிக்கப்பட்ட நேரமுத்திரை</strong> &mdash; புதுப்பிப்பு பொத்தானுக்கு அடுத்து, தரவு கடைசியாக எப்போது பெறப்பட்டது என்பதை நேரமுத்திரை காட்டுகிறது (எ.கா. "புதுப்பிக்கப்பட்டது 09:15"). காட்டப்படும் தகவல் எவ்வளவு நடப்பு நிலையில் உள்ளது என்பதை இது சரியாக உங்களுக்குச் சொல்கிறது.',
        's5_tip' => 'செயலற்ற கண்காணிப்புக்காக Watchtower-ஐ ஒரு பிரத்யேக உலாவி தாவலில் திறந்து வைத்திருங்கள். 5-நிமிட புதுப்பிப்பு சுழற்சி என்பது ஒவ்வொரு தொகுதியையும் கைமுறையாகச் சரிபார்க்க வேண்டிய அவசியமின்றி உங்கள் IT செயல்பாடுகளின் கிட்டத்தட்ட நிகழ்நேரக் காட்சி உங்களிடம் எப்போதும் இருக்கும் என்பதைக் குறிக்கிறது.',
        's6_title' => 'விரைவு குறிப்புகள்',
        's6_tip1_title' => 'உங்கள் நாளை இங்கே தொடங்குங்கள்',
        's6_tip1_desc' => 'விரைவான செயல்பாட்டு மேலோட்டத்திற்காக ஒவ்வொரு காலையும் முதலில் Watchtower-ஐ திறங்கள். காலை சரிபார்ப்புகள் முடிந்தனவா, ஏதேனும் டிக்கெட்டுகள் அவசரமா, அனைத்து சேவைகளும் ஆரோக்கியமாக உள்ளனவா என்பதை நொடிகளில் நீங்கள் காணலாம்.',
        's6_tip2_title' => 'சிவப்பு புள்ளிகள் முதலில்',
        's6_tip2_desc' => 'எல்லாவற்றிற்கும் முன் சிவப்பு நிலை புள்ளிகளைக் கவனியுங்கள். இவை உடனடி கவனம் தேவைப்படும் அவசர உருப்படிகளைக் குறிக்கின்றன &mdash; தோல்வியடைந்த சரிபார்ப்புகள், உயர் முன்னுரிமை டிக்கெட்டுகள் அல்லது பயனர்களை செயலில் பாதிக்கும் சேவை முடக்கங்கள்.',
        's6_tip3_title' => 'தாவ கிளிக் செய்யுங்கள்',
        's6_tip3_desc' => 'அந்தத் தொகுதிக்கு நேராக வழிநடத்த ஒரு அட்டையில் உள்ள எந்தத் தொகுதி பெயரையும் கிளிக் செய்யுங்கள். முதன்மை மெனு அல்லது வாஃபிள் வழிசெலுத்தலைப் பயன்படுத்த வேண்டிய அவசியமில்லை &mdash; கவனம் தேவைப்படும் இடத்திற்கு Watchtower ஒரு நேரடி குறுக்குவழியாக செயல்படுகிறது.',
        's6_tip4_title' => 'சமீபத்திய தகவலுக்கு புதுப்பியை அழுத்துங்கள்',
        's6_tip4_desc' => 'டாஷ்போர்டு ஒவ்வொரு 5 நிமிடங்களுக்கும் தானாகவே புதுப்பிக்கப்பட்டாலும், மிகச் சமீபத்திய தரவை நீங்கள் விரும்பும் எந்த நேரத்திலும் புதுப்பி பொத்தானைக் கிளிக் செய்யலாம். ஒரு சிக்கலைத் தீர்த்த பிறகு நிலை புள்ளி மாறிவிட்டதா என்பதை உறுதிப்படுத்த இது பயனுள்ளது.',
        's6_tip5_title' => 'குழுக் கூட்டங்களில் பயன்படுத்துங்கள்',
        's6_tip5_desc' => 'ஸ்டாண்ட்-அப் அல்லது செயல்பாட்டு மறுஆய்வுக் கூட்டங்களின் போது Watchtower-ஐ ஒரு திரையில் காட்டுங்கள். எந்தப் பகுதிகளுக்கு கவனம் தேவை என்பதை விவாதிக்கவும், அம்பர் அல்லது சிவப்பு உருப்படிகளுக்கு உரிமையை ஒதுக்கவும் நிறக் குறியீட்டு புள்ளிகள் எளிதாக்குகின்றன.',
        's6_tip6_title' => 'பச்சை என்றால் அனைத்தும் தெளிவு',
        's6_tip6_desc' => 'டாஷ்போர்டில் உள்ள ஒவ்வொரு புள்ளியும் பச்சையாக இருக்கும்போது, உங்கள் IT செயல்பாடுகள் நல்ல நிலையில் உள்ளன. அவசர டிக்கெட்டுகள் இல்லை, தோல்வியடைந்த சரிபார்ப்புகள் இல்லை, காலாவதியாகும் ஒப்பந்தங்கள் இல்லை, அனைத்து சேவைகளும் இயங்குகின்றன. அதுவே இலக்கு.',
        's7_title' => 'அமைப்புகள்',
        's7_intro' => 'Watchtower → அமைப்புகள் எந்த அட்டைகள் தோன்றும், எந்த வரிசையில், ஒவ்வொரு எண்ணும் எதை எண்ணுகிறது என்பதைத் தீர்மானிக்கிறது. அங்குள்ள அனைத்தும் ஏற்கனவே சரியாக உள்ள டாஷ்போர்டை மெருகேற்றுவதே: முழுத் திரையையும் தொடாமல் விட்டால் ஒவ்வொரு அட்டையும் வரையப்படும், ஒவ்வொரு நிலையும் எண்ணப்படும், எனவே எண்கள் சரியாக இருக்க எதையும் உள்ளமைக்கத் தேவையில்லை.',
        's7_cards_title' => 'அட்டைகள்',
        's7_cards_desc' => 'உங்கள் குழு கவனிக்காத பதின்மூன்று அட்டைகளில் எதையும் முடக்குங்கள், மீதமுள்ளவற்றை உங்கள் குழு படிக்கும் வரிசையில் வையுங்கள் - ஒரு அட்டையை அதன் கைப்பிடியால் இழுக்கவும், அம்புகளைப் பயன்படுத்தவும், அல்லது ஒன்றைத் தேர்ந்தெடுத்து Alt உடன் ஓர் அம்புக்குறியை அழுத்தவும். வரிசை அனைவருக்கும் ஒன்றே; ஒவ்வொருவரும் தங்களுக்கு அணுகல் உள்ள அட்டைகளை மட்டுமே காண்பார்கள். வரிசையை மீட்டமை உள்ளமைந்த வரிசையைத் திரும்பக் கொண்டுவரும். எதுவும் இழக்கப்படாது - ஒவ்வொரு தொகுதியும் தனது சொந்தத் திரைகளில் எல்லாவற்றையும் தொடர்ந்து காட்டும்.',
        's7_counts_title' => 'எண்ணிக்கைகள்',
        's7_counts_desc' => 'ஒவ்வொரு எண்ணிக்கையிலும் உங்களிடம் உள்ள ஒவ்வொரு நிலையும் அடங்கும்; அதனால்தான் ஒன்றை மறுபெயரிடுவதும் சேர்ப்பதும் எங்கும் பட்டியலிடப்படாமலே வேலை செய்கிறது. ஒரு அட்டை நீங்கள் ஒரே பார்வையில் படிக்க விரும்புவதை விட அதிகமாகக் காட்டினால் மட்டுமே ஒன்றைக் குறுக்குங்கள். ஒவ்வொரு வரிசையும் அது பாதிக்கும் தொகுதியின் நிறத்தில் அந்தத் தொகுதியால் குறிக்கப்பட்டுள்ளது.',
        's7_mc_title' => 'எந்தக் காலை சரிபார்ப்புகள் சிக்கலாகக் கருதப்படும்',
        's7_mc_desc' => 'உங்கள் காலை சரிபார்ப்பு நிலைகளில் எது தேர்ச்சி, எது தோல்வி என்பதை FreeITSM-இல் எதுவும் பதிவு செய்வதில்லை — அவை உங்கள் சொந்த லேபிள்கள். நீங்கள் சொல்லும் வரை, அட்டை உங்கள் சொந்த வரிசையில் முதல் நிலையை மட்டுமே நல்லதாகக் கருதும், சரிபார்ப்புகள் தேர்ச்சி பெற்றன என்பதற்குப் பதிலாக முடிந்தன என்று தெரிவிக்கும். சிக்கலைக் குறிப்பவற்றைப் பெயரிடுங்கள், அது அதைப் பயன்படுத்தும்.',
        's7_red_title' => 'எந்தச் சேவைச் சிக்கல்கள் விளக்கை சிவப்பாக்கும்',
        's7_red_desc' => 'ஒவ்வொரு பாதிப்பு நிலையின் "செயலிழப்பாகக் கணக்கிடு" அமைப்பிலிருந்து வேண்டுமென்றே தனியாகத் தேர்ந்தெடுக்கப்படுகிறது: அது உங்கள் இயக்க நேர சதவீதங்களை நிர்ணயிக்கிறது, எனவே இங்கே ஒரு நிறத்தை மாற்ற உங்கள் அறிக்கையிடலை நீங்கள் ஒருபோதும் திரிக்க வேண்டியிருக்கக் கூடாது. மாற்றாமல் விட்டால் அந்த நிலைகளையே பின்பற்றும், எனவே நீங்கள் வேறு விதமாகச் சொல்லும் வரை எதுவும் மாறாது.',
        's7_paused_title' => 'மிக நீண்ட நேரம் இடைநிறுத்தம்',
        's7_paused_desc' => 'Watchtower குறிப்பிடுவதற்கு முன், ஒரு டிக்கெட் அதன் SLA கடிகாரம் நிறுத்தப்பட்ட நிலையில் எத்தனை மணிநேரம் இருக்கலாம். இயல்புநிலை 24.',
    ],
    'scope' => [
        'mine' => 'என்னுடையது',
        'team' => 'என் குழு',
        'all' => 'அனைவரும்',
        'everyone_tag' => 'அனைவரும்',
        'impersonal_heading' => '“என்னுடையது” என்பதில், உரிமையாளர் இல்லாத அட்டைகள்',
        'impersonal_show' => 'தொடர்ந்து காட்டு',
        'impersonal_hide' => 'மறை',
        'impersonal_note' => 'சேவை நிலை, பணிப்பாய்வுகள், உபகரணங்கள், பகிரப்பட்ட நாட்காட்டி, ஒப்பந்தங்கள், அறிவுத்தளம், மென்பொருள் உரிமங்கள் மற்றும் டொமைன்கள் ஒரு நபருக்கு அல்லாமல் குழுவுக்குச் சொந்தமானவை, எனவே அவற்றை உங்களுக்காகச் சுருக்க முடியாது. அவற்றை வைத்திருப்பதே பாதுகாப்பான பதில்: நீங்கள் தனிப்பட்ட பார்வைக்கு மாறியதால் மறைந்துபோகக் கூடாத கடைசி விஷயம் பாதிக்கப்பட்ட சேவை.',
